      lbl(S, 'l1', 19.0, 3.5, ['문자열은 읽기 전용 바이트와 16B 헤더 · UTF-8이라 한글은 글자당 3바이트', 'read-only bytes behind a 16-byte header; in UTF-8 a Hangul syllable takes 3 bytes'], 'a', 1, { w: 12.4 });
      chip(S, 'b2', 21.0, 1.9, .92, 'ed', 'danger', 2, { h: .8 }); T(S, 'ix', 21.0, 2.8, '↑ s[2]', 'cz-mono gox-tiny gox-r', 2, { w: 1.8 });
      lbl(S, 'l2', 19.0, 4.9, ['s[i]는 i번째 바이트 · 글자 중간을 잘라 깨진 문자가 될 수 있어요', 's[i] is the i-th byte, which can cut a character in half'], 'w', 2, { w: 12.4 });
