      lbl(S, 'l3', 19.0, 6.9, ['range는 UTF-8을 풀어 룬(코드 포인트)과 시작 바이트 위치를 줘요', 'range decodes UTF-8, yielding each rune (code point) and its starting byte index'], 'g', 3, { w: 12.4 });
