function sEscape() {
  return CW('go-escape', {
    code: ['func newUser() *User {', ['    u := User{"kim", 30}   // 힙으로 이동', '    u := User{"kim", 30}   // moved to heap'], '    return &u', '}', ['xs := make([]int, 8)       // 스택: 탈출 안 함', 'xs := make([]int, 8)       // stack: no escape'], ['go build -gcflags=-m       // 판단 보기', 'go build -gcflags=-m       // show decisions']],
    hl: [[0, 4, 'warn'], [4, 1, 'ok'], [0, 5], [5, 1, 'ok']],
    draw: (S) => {
      rect(S, 'stb', 19.0, .5, 5.8, 2.4, 'ok', 8, 1, { r: .2 }); T(S, 'stt', 19.2, .55, ['스택', 'stack'], 'gox-tiny gox-g', 1, { w: 3.0 });
      rect(S, 'hpb', 25.6, .5, 5.8, 2.4, 'warn', 8, 1, { r: .2 }); T(S, 'hpt', 25.8, .55, ['힙', 'heap'], 'gox-tiny gox-w', 1, { w: 3.0 });
      chip(S, 'pp', 19.4, 1.1, 3.0, 'p *User', 'accent', 1, { h: .8 }); chip(S, 'uh', 26.0, 1.1, 5.0, 'u {kim 30}', 'warn', 1, { h: .8 }); arw(S, 'ppa', [22.5, 1.5], [25.9, 1.5], 1);
      chip(S, 'xs', 19.4, 2.0, 4.6, 'xs [8]int', 'ok', 2, { h: .8 });
      lbl(S, 'l1', 19.0, 3.2, ['u를 가리키는 포인터가 함수 밖에 남으니 컴파일러가 u를 힙에 둬요 · C와 달리 댕글링이 없어요', 'a pointer to u outlives the call, so u goes to the heap; nothing dangles, unlike C'], 'w', 1, { w: 12.4 });
      lbl(S, 'l2', 19.0, 4.6, ['밖으로 나가지 않는 값은 스택에서 공짜로 사라져요 · 크기가 변수면 힙으로', 'values that never leave vanish from the stack for free; a variable size goes to the heap'], 'g', 2, { w: 12.4 });
      [[['힙 24B', 'heap 24 B'], 18.26, 'warn', '18 ns'], [['스택', 'stack'], .14, 'ok', '~0 ns']].forEach(([n, v, c, t], i) => { const y = 6.0 + i * .6; T(S, 'en' + i, 19.0, y, n, 'gox-tiny', 3, { w: 3.0 }); hbar(S, 'eb' + i, 22.2, y + .05, v * .3, c, 3, { h: .45 }); T(S, 'ev' + i, 22.4 + v * .3, y, t, 'cz-mono gox-tiny', 3, { w: 2.0 }); });
      lbl(S, 'l3', 19.0, 7.3, ['힙 객체는 할당 비용에 GC 일까지 더해요 (이 환경에서 잰 값)', 'heap objects add GC work on top of allocation cost (measured here)'], 'w', 3, { w: 12.4 });
      mono(S, 'gm', 19.0, 8.7, ['main.go:13: moved to heap: u', 'main.go:16: make([]int, 8) does not escape'], 4, { w: 12.4, dy: .55, c: 'gox-g' });
      lbl(S, 'l4', 19.0, 9.95, ['-gcflags=-m으로 컴파일러의 판단을 그대로 볼 수 있어요', '-gcflags=-m shows the compiler’s decisions directly'], 'g', 4, { w: 12.4 });
      lbl(S, 'm4', 1, 8.1, ['뜨거운 경로에서는 -benchmem의 allocs/op를 줄여요', 'in hot paths, drive down the allocs/op reported by -benchmem'], 'a', 4, { w: 16.0 });
    },
    notes: [['Go에는 스택과 힙을 고르는 문법이 없고, 컴파일러가 탈출 분석으로 정해요 · newUser가 지역 변수 u의 주소를 돌려주면 u는 함수가 끝난 뒤에도 쓰이므로, 컴파일러가 u를 힙으로 옮겨요(moved to heap: u) · 그래서 C처럼 사라진 스택을 가리키는 일이 없어요', 'Go has no syntax for choosing stack or heap; the compiler decides by escape analysis: since newUser returns the address of its local u, u is used after the function returns, so the compiler moves it to the heap (moved to heap: u), and nothing ever points into a vanished stack as in C'], ['make([]int, 8)처럼 함수 밖으로 나가지 않고 크기도 컴파일 때 정해진 값은 스택에 놓여, 함수가 끝나면 비용 없이 사라져요 · 이 환경에서 sum은 할당 0번이었어요 · 반면 make([]int, n)처럼 크기가 변수면 힙으로 가요', 'a value such as make([]int, 8) that never leaves the function and has a compile-time size lives on the stack and disappears at no cost when the function ends (sum made zero allocations here), whereas a variable size as in make([]int, n) goes to the heap'], ['이 환경에서 24바이트 구조체를 힙에 할당하는 데 약 18ns가 걸렸고, 스택에서는 거의 0이었어요 · 힙 객체는 나중에 GC가 찾아다니며 확인해야 해서, 할당이 많을수록 GC 일도 늘어요', 'allocating a 24-byte struct on the heap took about 18 ns here, versus almost nothing on the stack, and since the GC must later trace heap objects, more allocations also mean more GC work'], ['go build -gcflags=-m으로 컴파일러가 무엇을 왜 힙으로 보냈는지 줄마다 볼 수 있어요 · 성능이 중요한 경로에서는 벤치마크의 allocs/op를 보며 포인터 반환, 인터페이스 변환, 클로저 캡처로 생기는 탈출을 줄여요', 'go build -gcflags=-m shows, line by line, what the compiler sent to the heap and why, and on performance-critical paths you watch allocs/op in benchmarks while reducing escapes caused by returning pointers, interface conversions and closure captures']],
    fin: [['스택이냐 힙이냐는 컴파일러가 정해요', 'the compiler decides between stack and heap', 'gox-xs gox-a'], ['밖으로 새는 포인터가 힙 할당을 부르고', 'pointers that leak out cause heap allocation'], ['-gcflags=-m과 -benchmem으로 확인해요', 'check with -gcflags=-m and -benchmem']],
    caps: [['힙으로 탈출', 'Escaping to the heap'], ['스택에 남기', 'Staying on the stack'], ['할당 비용', 'The cost of allocation'], ['판단 보기', 'Seeing the decisions'], ['탈출 분석', 'Escape analysis']]
  });
}

